// Exact literal bounded six-DC-turn connector search. No unproved guards.
#include <bits/stdc++.h>
using namespace std; using K=long long;
struct P{int x,y;}; P rot(P p,int h){switch(h&3){case 0:return p;case 1:return{p.y,-p.x};case 2:return{-p.x,-p.y};default:return{-p.y,p.x};}}
K key(P p){return K((uint64_t(uint32_t(p.x))<<32)|uint32_t(p.y));}struct Macro{vector<pair<P,int>>req;vector<P>odd;P e;int dh;};vector<Macro>M(3);map<K,int>board;vector<pair<K,int>>undo;vector<int>word;P pos{0,0};int heading=0;long long nodes=0,leaves=0,hits=0;int bound;int ns[7];
bool apply(int a,bool protect){auto&m=M[a];auto old=undo.size();for(auto [z,v]:m.req){P r=rot(z,heading);P p{pos.x+r.x,pos.y+r.y};if(protect&&p.x==2&&p.y==0){while(undo.size()>old){auto[k,v]=undo.back();undo.pop_back();if(v<0)board.erase(k);else board[k]=v;}return false;}K k=key(p);auto it=board.find(k);if(it!=board.end()&&it->second!=v){while(undo.size()>old){auto[k,v]=undo.back();undo.pop_back();if(v<0)board.erase(k);else board[k]=v;}return false;}if(it==board.end()){undo.push_back({k,-1});board[k]=v;}}
for(P z:m.odd){P r=rot(z,heading);K k=key({pos.x+r.x,pos.y+r.y});undo.push_back({k,board[k]});board[k]^=1;}P r=rot(m.e,heading);pos={pos.x+r.x,pos.y+r.y};heading=(heading+m.dh)&3;word.push_back(a);return true;}
void rollback(size_t u,P p,int h,size_t w){while(undo.size()>u){auto[k,v]=undo.back();undo.pop_back();if(v<0)board.erase(k);else board[k]=v;}pos=p;heading=h;word.resize(w);}
void dfs(int lev){nodes++;size_t u=undo.size(),ww=word.size();P pp=pos;int hh=heading;
if(lev==5){int n5=ns[3]-ns[1]-2,n6=ns[0]+ns[4]-ns[2];if(n5<0||n5>bound||n6<0||n6>bound)return;ns[5]=n5;ns[6]=n6;bool ok=true;for(int i=0;i<n5&&ok;i++)ok=apply(0,true);if(ok)ok=apply(1,true);for(int i=0;i<n6&&ok;i++)ok=apply(0,true);if(ok){leaves++;if(pos.x!=2||pos.y!=2||heading!=2)abort();if(apply(2,false)){hits++;cout<<"HIT";for(int n:ns)cout<<' '<<n;cout<<" WORD";for(int a:word)cout<<' '<<a;cout<<endl;}}rollback(u,pp,hh,ww);return;}
int mx=lev==3?2*bound+2:bound;for(int n=0;n<=mx;n++){ns[lev]=n;bool eligible=lev!=3||(n>=ns[1]+2&&n<=ns[1]+bound+2);if(eligible){size_t u1=undo.size(),w1=word.size();P p1=pos;int h1=heading;if(apply(1,true))dfs(lev+1);rollback(u1,p1,h1,w1);}if(n<mx&&!apply(0,true))break;}rollback(u,pp,hh,ww);}
int main(int argc,char**argv){ifstream f(argv[1]);bound=atoi(argv[2]);for(auto&m:M){int nr,no;f>>m.e.x>>m.e.y>>m.dh>>nr>>no;for(int i=0;i<nr;i++){P p;int v;f>>p.x>>p.y>>v;m.req.push_back({p,v});}for(int i=0;i<no;i++){P p;f>>p.x>>p.y;m.odd.push_back(p);}}if(!apply(0,false))abort();dfs(0);cout<<"DONE bound "<<bound<<" nodes "<<nodes<<" leaves "<<leaves<<" hits "<<hits<<endl;}
